import { chromium, expect, test, type Page } from "@playwright/test";
import { execFileSync } from "node:child_process";
import { createServer } from "node:http";
import { cp, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

// Real browser chrome events cannot be generated by page.evaluate or CDP DOM clicks.
// On Linux, run this regression under xvfb-run; XTest sends physical key events.
function nativeKeys(chords: string[][]) {
  execFileSync(
    "python3",
    [
      "-c",
      `
import ctypes,ctypes.util,time,json,sys
x=ctypes.CDLL(ctypes.util.find_library('X11'))
t=ctypes.CDLL(ctypes.util.find_library('Xtst'))
x.XOpenDisplay.argtypes=[ctypes.c_char_p];x.XOpenDisplay.restype=ctypes.c_void_p
x.XStringToKeysym.argtypes=[ctypes.c_char_p];x.XStringToKeysym.restype=ctypes.c_ulong
x.XKeysymToKeycode.argtypes=[ctypes.c_void_p,ctypes.c_ulong];x.XKeysymToKeycode.restype=ctypes.c_uint
x.XFlush.argtypes=[ctypes.c_void_p]
x.XCloseDisplay.argtypes=[ctypes.c_void_p]
t.XTestFakeKeyEvent.argtypes=[ctypes.c_void_p,ctypes.c_uint,ctypes.c_int,ctypes.c_ulong]
d=x.XOpenDisplay(None)
if not d: raise RuntimeError('No X11 display')
for chord in json.loads(sys.argv[1]):
 keys=[x.XKeysymToKeycode(d,x.XStringToKeysym(k.encode())) for k in chord]
 for k in keys:t.XTestFakeKeyEvent(d,k,1,0)
 x.XFlush(d);time.sleep(0.06)
 for k in reversed(keys):t.XTestFakeKeyEvent(d,k,0,0)
 x.XFlush(d);time.sleep(0.06)
x.XFlush(d);x.XCloseDisplay(d)
`,
      JSON.stringify(chords),
    ],
    { stdio: "pipe" },
  );
}

function invokeToolbarAction() {
  nativeKeys([["Alt_L", "Shift_L", "y"]]);
}
async function invokePageMenu(page: Page) {
  await page.evaluate(() => window.getSelection()?.removeAllRanges());
  await page.mouse.click(850, 550, { button: "right" });
  await page.waitForTimeout(350);
  // On Chromium's ordinary page menu the extension item precedes View page source and Inspect.
  nativeKeys([["End"], ["Up"], ["Up"], ["Return"]]);
}
async function selectTerm(page: Page) {
  await page.locator("#term").scrollIntoViewIfNeeded();
  await page.evaluate(() => {
    const range = document.createRange();
    range.selectNodeContents(document.getElementById("term")!);
    const selection = window.getSelection()!;
    selection.removeAllRanges();
    selection.addRange(range);
    document.dispatchEvent(new PointerEvent("pointerup", { bubbles: true }));
  });
}

test("未预授权网页：真实右键开关、独立划词解释、工具栏与页面隔离", async () => {
  test.skip(
    process.platform !== "linux" || !process.env.DISPLAY,
    "Requires Linux X11 (xvfb-run), libXtst and python3 for native browser actions.",
  );
  const requests: any[] = [];
  let slowClosed = false;
  const server = createServer(async (req, res) => {
    if (req.url === "/chat/completions") {
      let raw = "";
      for await (const chunk of req) raw += chunk;
      const body = JSON.parse(raw);
      requests.push(body);
      res.setHeader("Content-Type", "application/json");
      const result = JSON.stringify({
        choices: [
          { message: { content: "里程计解释：结合完整文档中的相关说明。" } },
        ],
      });
      if (body.messages.at(-1).content.includes("慢速测试")) {
        const timer = setTimeout(() => res.end(result), 10000);
        res.on("close", () => {
          slowClosed = true;
          clearTimeout(timer);
        });
      } else res.end(result);
      return;
    }
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.end(
      '<!doctype html><meta charset="utf-8"><title>未授权网页测试</title><body style="margin:40px;font:17px/1.8 system-ui"><main><h1>设备文档</h1><h2>位姿估计</h2><p id="term">里程计根据运动信息估计位姿。</p><p>普通段落一。</p><p>普通段落二。</p><h2>进一步说明</h2><p id="remote">里程计的完整说明 REMOTE_RELATED_CONTEXT，测量误差会累计。</p></main></body>',
    );
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  const origin = `http://127.0.0.1:${(server.address() as { port: number }).port}`;
  const temp = await mkdtemp(join(tmpdir(), "reader-permission-regression-"));
  const extension = join(temp, "extension");
  await cp(resolve("dist"), extension, { recursive: true });
  const manifest = JSON.parse(
    await readFile(join(extension, "manifest.json"), "utf8"),
  );
  // No host permission: both entry points must obtain the real activeTab grant.
  manifest.commands._execute_action = {
    suggested_key: { default: "Alt+Shift+Y" },
  };
  await writeFile(join(extension, "manifest.json"), JSON.stringify(manifest));
  const context = await chromium.launchPersistentContext(
    join(temp, "profile"),
    {
      channel: "chromium",
      headless: false,
      args: [
        `--disable-extensions-except=${extension}`,
        `--load-extension=${extension}`,
        "--no-sandbox",
      ],
      viewport: { width: 1000, height: 750 },
    },
  );
  try {
    const worker =
      context.serviceWorkers()[0] ||
      (await context.waitForEvent("serviceworker"));
    await worker.evaluate(() => {
      chrome.contextMenus.onClicked.addListener((info) => {
        void chrome.storage.session.set({ testMenuClick: info.menuItemId });
      });
      chrome.action.onClicked.addListener((tab) => {
        void chrome.storage.session.set({ testToolbarClick: tab.id });
      });
    });
    const page = await context.newPage();
    await page.goto(origin);
    await page.bringToFront();
    const tabId = await worker.evaluate(
      async () =>
        (await chrome.tabs.query({ active: true, currentWindow: true }))[0].id!,
    );
    expect(
      await worker.evaluate(
        async (id) => (await chrome.tabs.get(id)).url,
        tabId,
      ),
    ).toBeUndefined();
    expect(
      (await worker.evaluate(() => chrome.permissions.getAll())).origins || [],
    ).toEqual([]);
    await selectTerm(page);
    await expect(
      page.getByRole("dialog", { name: "阅读助手划词工具" }),
    ).toHaveCount(0);
    await invokePageMenu(page);
    await expect
      .poll(() =>
        worker.evaluate(
          async () =>
            (await chrome.storage.session.get("testMenuClick")).testMenuClick,
        ),
      )
      .toBe("reader-toggle");
    await expect(page.getByRole("status")).toContainText("阅读助手已打开");
    await expect(page.getByRole("status")).toContainText("已读取");
    const panels = () =>
      worker.evaluate(
        async () =>
          (await chrome.runtime.getContexts({ contextTypes: ["SIDE_PANEL"] }))
            .length,
      );
    expect(await panels()).toBe(0);
    expect(requests).toHaveLength(0);
    await selectTerm(page);
    const explain = page.getByRole("button", { name: "解释概念", exact: true });
    await expect(explain).toBeVisible();
    expect(requests).toHaveLength(0);
    await explain.click();
    await expect(
      page.getByRole("button", { name: "模型设置", exact: true }),
    ).toBeVisible();
    expect(await panels()).toBe(0);
    // Populate fixture credentials only in trusted extension storage. Model and
    // webpage origins coincide here; activeTab supplies the temporary origin grant.
    await worker.evaluate(async (baseUrl) => {
      await chrome.storage.local.set({
        modelConfig: {
          provider: "compatible",
          baseUrl,
          model: "fixture-model",
          maxTokens: 512,
          keyMode: "session",
        },
        preferences: { consent: false },
      });
      await chrome.storage.session.set({ apiKey: "fixture-test-key-not-real" });
    }, origin);
    await selectTerm(page);
    await explain.click();
    await expect(
      page.getByRole("button", { name: "了解并发送", exact: true }),
    ).toBeVisible();
    expect(requests).toHaveLength(0);
    await page.evaluate(() => {
      const root = document.getElementById("ai-reading-copilot")!.shadowRoot!;
      (
        Array.from(root.querySelectorAll("button")).find(
          (b) => b.textContent === "了解并发送",
        ) as HTMLButtonElement
      ).click();
    });
    expect(requests).toHaveLength(0);
    await page.getByRole("button", { name: "暂不发送", exact: true }).click();
    await explain.click();
    await page.getByRole("button", { name: "了解并发送", exact: true }).click();
    await expect(page.locator("#ai-reading-copilot .answer")).toContainText(
      "里程计解释",
    );
    expect(requests).toHaveLength(1);
    expect(requests[0].messages.at(-1).content).toContain(
      "REMOTE_RELATED_CONTEXT",
    );
    expect(await panels()).toBe(0);
    // Closing the small card does not disable reading mode.
    await page.getByRole("button", { name: "关闭", exact: true }).click();
    await selectTerm(page);
    await expect(explain).toBeVisible();
    // Full-document context is refreshed after a same-URL edit.
    await page.evaluate(() => {
      document.getElementById("remote")!.textContent =
        "里程计新版说明 UPDATED_RELATED_CONTEXT";
    });
    await expect(explain).toBeHidden();
    await selectTerm(page);
    await explain.click();
    await expect(page.locator("#ai-reading-copilot .answer")).toContainText(
      "里程计解释",
    );
    expect(requests.at(-1).messages.at(-1).content).toContain(
      "UPDATED_RELATED_CONTEXT",
    );
    expect(requests.at(-1).messages.at(-1).content).not.toContain(
      "REMOTE_RELATED_CONTEXT",
    );
    await invokePageMenu(page);
    await expect(page.getByRole("status")).toContainText("阅读助手已关闭");
    await selectTerm(page);
    await expect(explain).toBeHidden();
    // The toolbar follows the same inline mode and never opens a panel.
    invokeToolbarAction();
    await expect(page.getByRole("status")).toContainText("阅读助手已打开");
    expect(await panels()).toBe(0);
    await expect
      .poll(() =>
        worker.evaluate(
          async () =>
            (await chrome.storage.session.get("testToolbarClick"))
              .testToolbarClick,
        ),
      )
      .toBe(tabId);
    const second = await context.newPage();
    await second.goto(origin + "/second");
    await second.bringToFront();
    expect(
      await worker.evaluate(
        async () =>
          (await chrome.tabs.query({ active: true, currentWindow: true }))[0]
            .url,
      ),
    ).toBeUndefined();
    await selectTerm(second);
    await expect(
      second.getByRole("dialog", { name: "阅读助手划词工具" }),
    ).toHaveCount(0);
    invokeToolbarAction();
    await expect(second.getByRole("status")).toContainText("阅读助手已打开");
    await selectTerm(second);
    await expect(
      second.getByRole("button", { name: "解释概念", exact: true }),
    ).toBeVisible();
    expect(await panels()).toBe(0);
    await second.reload();
    await expect
      .poll(() =>
        worker.evaluate(
          async () =>
            Object.keys(await chrome.storage.session.get(null)).filter((k) =>
              k.startsWith("reader-"),
            ).length,
        ),
      )
      .toBe(1);
    await selectTerm(second);
    await expect(
      second.getByRole("button", { name: "解释概念", exact: true }),
    ).toHaveCount(0);
    await page.bringToFront();
    await page.evaluate(() => {
      document.getElementById("term")!.textContent = "慢速测试里程计";
    });
    await page.waitForTimeout(1000);
    await selectTerm(page);
    await explain.click();
    await expect
      .poll(() => requests.at(-1).messages.at(-1).content.includes("慢速测试"))
      .toBe(true);
    invokeToolbarAction();
    await expect(page.getByRole("status")).toContainText("阅读助手已关闭");
    await expect.poll(() => slowClosed).toBe(true);
    await expect(explain).toBeHidden();
    invokeToolbarAction();
    await expect(page.getByRole("status")).toContainText("阅读助手已打开");
    await page.evaluate(() => {
      history.pushState({}, "", "/new-document");
      document
        .querySelector("main")!
        .insertAdjacentHTML("beforeend", "<p>另一个文档</p>");
    });
    await expect
      .poll(() =>
        worker.evaluate(
          async () =>
            Object.keys(await chrome.storage.session.get(null)).filter((k) =>
              k.startsWith("reader-"),
            ).length,
        ),
      )
      .toBe(0);
    await selectTerm(page);
    await expect(explain).toBeHidden();
    expect(
      (await worker.evaluate(() => chrome.permissions.getAll())).origins || [],
    ).toEqual([]);
  } finally {
    await context.close();
    await new Promise<void>((r) => server.close(() => r()));
    await rm(temp, { recursive: true, force: true });
  }
});
